create table if not exists public.permits (id bigint generated by default as identity primary key,permit_number text unique not null,player_name text not null,permit_type text not null,region text not null,valid_until date not null,created_at timestamptz not null default now()); alter table public.permits enable row level security; drop policy if exists "public read permits" on public.permits; create policy "public read permits" on public.permits for select to anon using (true); drop policy if exists "public create permits" on public.permits; create policy "public create permits" on public.permits for insert to anon with check (char_length(player_name) between 1 and 80 and char_length(permit_number) between 8 and 30);